const menu=document.getElementById('menu-button'),mobile=document.getElementById('mobile-nav');if(menu&&mobile)menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));mobile.hidden=!open});
const share=document.getElementById('share-guide');if(share)share.addEventListener('click',async()=>{try{if(navigator.share)await navigator.share({title:document.title,url:location.href});else{await navigator.clipboard.writeText(location.href);share.textContent='¡Link copiado! ✓'}}catch{}});
const form=document.getElementById('live-search');if(form){const input=document.getElementById('search-input'),results=document.getElementById('search-results'),count=document.getElementById('result-count'),buttons=[...document.querySelectorAll('#filters button')];let entries=[],current='all';const normalize=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function render(){const q=normalize(input.value).trim();const terms=q.split(/\s+/).filter(Boolean);let found=entries.filter(e=>(current==='all'||e.category===current)&&terms.every(t=>normalize(e.title+' '+e.description+' '+e.categoryName).includes(t)));count.textContent=`${found.length} ${found.length===1?'guía encontrada':'guías encontradas'}`;results.replaceChildren();if(!found.length){let p=document.createElement('p');p.className='empty-state';p.textContent='Todavía no tenemos una guía publicada para esa búsqueda. Probá con otras palabras o explorá otro universo.';results.append(p)}else for(let e of found){const a=document.createElement('a');a.className='guide-item';a.href=e.url;const s=document.createElement('span');s.className='guide-category';s.textContent=e.categoryName;const b=document.createElement('strong');b.textContent=e.title;const ar=document.createElement('span');ar.textContent='↗';a.append(s,b,ar);results.append(a)}}form.addEventListener('submit',e=>e.preventDefault());input.addEventListener('input',()=>{render();const url=new URL(location.href);if(input.value)url.searchParams.set('q',input.value);else url.searchParams.delete('q');history.replaceState(null,'',url)});buttons.forEach(btn=>btn.addEventListener('click',()=>{current=btn.dataset.cat;buttons.forEach(x=>{x.classList.toggle('active',x===btn);x.setAttribute('aria-pressed',String(x===btn))});render()}));fetch('/search-index.json').then(r=>{if(!r.ok)throw Error('index');return r.json()}).then(data=>{entries=data;input.value=new URLSearchParams(location.search).get('q')||'';render()}).catch(()=>{count.textContent='No se pudo cargar el buscador. Volvé a intentar más tarde.'})}
